        (wr_skip((off_t)(BCPIO_PAD(sizeof(HD_BCPIO) + nsz))) < 0)) {
      Tty.paxwarn(true, "Could not write bcpio header for %s", arcn.org_name);
      return .failed;
    }

    /*
     * if we have file data, tell the caller we are done
     */
    if ((arcn.type == PAX_CTG) || (arcn.type == PAX_REG) ||
        (arcn.type == PAX_HRG)) {
      return .ok
    }

    /*
     * if we are not a link, tell the caller we are done, go to next file
     */
    if (arcn.type != PAX_SLK) {
      return .partial
    }

    /*
     * write the link name, tell the caller we are done.
     */
    if ((wr_rdbuf(arcn.ln_name, arcn.ln_nlen) < 0) ||
        (wr_skip((off_t)(BCPIO_PAD(arcn.ln_nlen))) < 0)) {
      Tty.paxwarn(true,"Could not write bcpio link name for %s",arcn.org_name);
      return .failed;
    }
    return .partial

  out:
    /*
     * header field is out of range
     */
    Tty.paxwarn(true,"Bcpio header field is too small for file %s", arcn.org_name);
    return .partial
  }



  // ==============================================================================


  /*
   * bad_opt()
   *  generic routine used to complain about a format specific options
   *  when the format does not support options.
   */

  func other_options() throws(CmdErr) { // was bad_opt
    OPLIST *opt;

    if (ophead == NULL) {
      return
    }
    /*
     * print all we were given
     */
    Tty.paxwarn(true,"These format options are not supported");

    while ((opt = opt_next()) != NULL) {
      if (opt->separator == SEP_EQ) {
        (void)fprintf(stderr, "\t%s = %s\n", opt->name, opt->value);
      } else if (opt->separator == SEP_COLONEQ ) {
        (void)fprintf(stderr, "\t%s := %s\n", opt->name, opt->value);
      } else {  /* SEP_NONE */
        (void)fprintf(stderr, "\t%s\n", opt->name);
      }
    }

    throw CmdErr(1)  // pax_usage();
  }


}
